python3 << 'PYEOF'
import os
import re
from collections import defaultdict

ROOT = "/bench/repo"

# Persistent entity types: primary record structs in store package (map to DB tables)
ENTITY_TYPES = [
    "User", "UserSetting", "Memo", "MemoRelation", "Attachment",
    "IdentityProvider", "Inbox", "Reaction", "MemoShare", "UserIdentity",
    "InstanceSetting",
]

# Proto store entity/payload types (from proto/store, generated in proto/gen/store)
PROTO_ENTITY_TYPES = [
    "User", "UserSetting", "MemoPayload", "IdentityProvider", "InboxMessage",
    "InstanceSetting", "AttachmentPayload",
]

def is_data_layer(path):
    rel = path[len(ROOT)+1:] if path.startswith(ROOT+"/") else path
    # store/ tree is data layer
    if rel.startswith("store/"):
        return True
    # proto store generated code
    if rel.startswith("proto/gen/store/"):
        return True
    return False

def is_test_file(path):
    return path.endswith("_test.go") or "/test/" in path

def get_package_dir(path):
    return os.path.dirname(path)

def find_go_files():
    for dirpath, dirnames, filenames in os.walk(ROOT):
        # skip .git
        if ".git" in dirnames:
            dirnames.remove(".git")
        for fn in filenames:
            if fn.endswith(".go"):
                yield os.path.join(dirpath, fn)

# Detect import alias for store package per file
store_import_re = re.compile(
    r'(?:^|\s)(\w+)\s+"github\.com/usememos/memos/store"'
)
storepb_import_re = re.compile(
    r'(?:^|\s)(\w+)\s+"github\.com/usememos/memos/proto/gen/store"'
)
# Also bare import without alias defaults to last path component = "store"
bare_store_re = re.compile(r'^\s*"github\.com/usememos/memos/store"', re.M)
bare_storepb_re = re.compile(r'^\s*"github\.com/usememos/memos/proto/gen/store"', re.M)

def get_aliases(content):
    aliases = set()
    for m in store_import_re.finditer(content):
        aliases.add(m.group(1))
    if bare_store_re.search(content):
        aliases.add("store")
    storepb_aliases = set()
    for m in storepb_import_re.finditer(content):
        storepb_aliases.add(m.group(1))
    if bare_storepb_re.search(content):
        storepb_aliases.add("store")
    return aliases, storepb_aliases

# Count distinct package dirs referencing each entity
def count_entities(entity_types, alias_prefix_fn):
    # results[entity][category] = set of package dirs
    results = {e: {"prod": set(), "all": set()} for e in entity_types}

    for path in find_go_files():
        if is_data_layer(path):
            continue
        with open(path, "r", errors="replace") as f:
            content = f.read()

        store_aliases, storepb_aliases = get_aliases(content)
        if not store_aliases and not storepb_aliases:
            continue

        pkg_dir = get_package_dir(path)
        is_test = is_test_file(path)

        for entity in entity_types:
            prefix = alias_prefix_fn(store_aliases, storepb_aliases, entity)
            if not prefix:
                continue
            # Match type references: prefix.Entity, *prefix.Entity, etc.
            pattern = re.compile(r'\b' + re.escape(prefix) + r'\.' + re.escape(entity) + r'\b')
            if pattern.search(content):
                results[entity]["all"].add(pkg_dir)
                if not is_test:
                    results[entity]["prod"].add(pkg_dir)

    return results

def store_prefix(aliases, _, entity):
    if aliases:
        # use 'store' if present else first alias
        return "store" if "store" in aliases else next(iter(aliases))
    return None

def storepb_prefix(_, pb_aliases, entity):
    if pb_aliases:
        return "storepb" if "storepb" in pb_aliases else next(iter(pb_aliases))
    return None

store_results = count_entities(ENTITY_TYPES, store_prefix)
storepb_results = count_entities(PROTO_ENTITY_TYPES, storepb_prefix)

print("=== store package record types (external distinct package dirs) ===")
ranked = sorted(ENTITY_TYPES, key=lambda e: (-len(store_results[e]["prod"]), -len(store_results[e]["all"]), e))
for e in ranked:
    print(f"  {e:20s}  prod={len(store_results[e]['prod']):3d}  total={len(store_results[e]['all']):3d}")

print("\n=== proto/gen/store types (external distinct package dirs) ===")
