  print "#" . ($i+1) . " $e: prod=" . scalar(@pkgs) . ", total=" . count_keys($store_results{$e}{all}) . "\n";
    my $n = @pkgs > 10 ? 10 : @pkgs;
    for my $j (0..$n-1) {
