BEGIN {
    split("User UserSetting Memo MemoRelation Attachment IdentityProvider Inbox Reaction MemoShare UserIdentity InstanceSetting", entities, " ")
    nentities = length(entities)
}
function is_test(path) {
    return (path ~ /_test\.go$/ || path ~ /\/test\//)
}
function add_ref(entity, pkg, path,   is_t) {
    all_pkgs[entity, pkg] = 1
    is_t = is_test(path)
    if (!is_t) prod_pkgs[entity, pkg] = 1
}
{
    path = FILENAME
    pkg = path
    sub(/\/[^\/]+$/, "", pkg)

    has_store = 0
    store_prefix = ""
    if (match($0, /[[:space:]]([A-Za-z_][A-Za-z0-9_]*)[[:space:]]+"github\.com\/usememos\/memos\/store"/, m)) {
        has_store = 1
        store_prefix = m[1]
    } else if ($0 ~ /"github\.com\/usememos\/memos\/store"/) {
        has_store = 1
        store_prefix = "store"
    }

    if (has_store) {
        for (i = 1; i <= nentities; i++) {
            e = entities[i]
            pat = "\\y" store_prefix "\\." e "\\y"
            if ($0 ~ pat) add_ref(e, pkg, path)
        }
    }
}
END {
    for (i = 1; i <= nentities; i++) {
        e = entities[i]
        prod = 0; total = 0
        for (k in prod_pkgs) {
            split(k, parts, SUBSEP)
            if (parts[1] == e) prod++
        }
        for (k in all_pkgs) {
            split(k, parts, SUBSEP)
            if (parts[1] == e) total++
        }
        printf "%s %d %d\n", e, prod, total
    }
}

